          now,
          state,
          redirectUrl,
          redirectCanonicalUrl,
          redirectSeed,
          currentUrl,
          currentRenderedSearch,
          state.root,
          freshnessPolicy,
          nextUrl,
          scrollBehavior,
          navigateType,
          navigationLock,
          // A server-action redirect navigation is bound to the shared map.
          segmentCacheMap,
          null,
